files.content:
:root {
  --bg: #1e293b;
  --card: #f8fafc;
  --primary: #0f766e;
  --primary-dark: #115e59;
  --accent: #f59e0b;
  --text: #1e293b;
  --text-light: #64748b;
  --danger: #b91c1c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 1rem;
}

.meter-card {
  background: var(--card);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  color: var(--text);
  margin-bottom: 1.5rem;
  letter-spacing: 0.02em;
}

.meter-display {
  display: flex;
  justify-content: space-around;
  gap: 1rem;
  margin-bottom: 1.5rem;
  padding: 1rem;
  background: #e2e8f0;
  border-radius: 1rem;
}

.time-display,
.price-display {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.label {
  font-size: 0.875rem;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.max-message {
  color: var(--danger);
  font-weight: 600;
  margin-bottom: 1rem;
  font-size: 0.95rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

button {
  flex: 1 1 auto;
  min-width: 100px;
  padding: 0.875rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 0.75rem;
  cursor: pointer;
  background: var(--primary);
  color: #ffffff;
  transition: background 0.15s, transform 0.1s;
  font-family: inherit;
}

button:hover {
  background: var(--primary-dark);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

#clear {
  background: var(--accent);
  color: var(--text);
}

#clear:hover {
  background: #d97706;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .meter-card {
    padding: 1.5rem 1rem;
  }
  .value {
    font-size: 1.75rem;
  }
  button {
    min-width: 80px;
    padding: 0.75rem 0.5rem;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const MAX_MINUTES = 180;
  const PRICE_PER_HOUR = 2.0;

  let totalMinutes = 0;

  const timeValue = document.getElementById('time-value');
  const priceValue = document.getElementById('price-value');
  const maxMessage = document.getElementById('max-message');
  const add15 = document.getElementById('add-15');
  const add60 = document.getElementById('add-60');
  const clearBtn = document.getElementById('clear');

  function formatTime(minutes) {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return h + ':' + String(m).padStart(2, '0');
  }

  function formatPrice(minutes) {
    const price = (minutes / 60) * PRICE_PER_HOUR;
    return '$' + price.toFixed(2);
  }

  function updateDisplay() {
    timeValue.textContent = formatTime(totalMinutes);
    priceValue.textContent = formatPrice(totalMinutes);

    const atMax = totalMinutes >= MAX_MINUTES;
    maxMessage.hidden = !atMax;
    add15.disabled = atMax;
    add60.disabled = atMax;
  }

  function addMinutes(min) {
    totalMinutes = Math.min(totalMinutes + min, MAX_MINUTES);
    updateDisplay();
  }

  function clearMeter() {
    totalMinutes = 0;
    updateDisplay();
  }

  add15.addEventListener('click', function () {
    addMinutes(15);
  });

  add60.addEventListener('click', function () {
    addMinutes(60);
  });

  clearBtn.addEventListener('click', clearMeter);

  updateDisplay();
})();
